def merge_sorted_arrays(a, b):
    c = []
    while a and b:
        if a[0] < b[0]:
            c.append(a.pop(0))
        else:
            c.append(b.pop(0))
    c.extend(a or b)
    return c

print(merge_sorted_arrays([1, 3, 5], [2, 4, 6]))

def duplicate_count(text):
    text = text.lower()
    count = 0
    for char in set(text):
        if text.count(char) > 1:
            count += 1
    return count

